  "high_order_assessment": [
    {
      "active_model_action": false,
      "citations": [],
      "completion": "not_triggered",
      "explanation": "HO1 requires eliciting a practical barrier, offering a stepwise alternative, and assigning who will do what next with a backup route. The doctor asked about school and gave activity restrictions, but did not elicit specific barriers like inability to return immediately, unclear hospital portal access, or lack of daytime caregiver. The follow-up plan and school accommodation were given without negotiating a barrier. This is a routine safety duty under RC5/RC8, not a distinct high-order adaptation.",
      "ho_id": "HO1",
